        public float Discount
        {
            get
            {
                var ProductOrders = App.Database.orders.Where(o => o.order_items.Any(oi => oi.positions.product_name == this.name));

                DateTime currentMonth = new DateTime(DateTime.Today.Year, DateTime.Today.Month, 1);
                DateTime lastMonth = currentMonth.AddMonths(-1);

                if (!ProductOrders.Any(o => o.date >= lastMonth && o.date < currentMonth)) return 0.25f;

                return 0.0f;
            }
        }

        public int DiscountedPrice
